(()=>{document.addEventListener("DOMContentLoaded",()=>{let r=document.querySelectorAll(".ws-product-videos video");if(!r.length)return;let t=new IntersectionObserver(e=>{e.forEach(n=>{if(!n.isIntersecting)return;let o=n.target;o.preload==="none"&&(o.preload="metadata"),t.unobserve(o)})},{rootMargin:"200px 0px"});r.forEach(e=>{t.observe(e)})});})();
